# ---------------------------------------------------------------- 匹配池

def _clean_title(s):
    s = re.sub(r"!?\[([^\]]*)\]\([^)]*\)", r"\1", s or "")      # 链接
    s = s.replace("**", "").replace("__", "").replace("`", "").strip()
    # 状态标记与编号可能交替出现（"### 1. [OA] 标题"），故循环剥离
    for _ in range(4):
        before = s
        s = re.sub(r"^\[(OA|收|已|新|待)\]\s*", "", s)
        s = re.sub(r"^(#{1,6}|[-*>]|\d+[.)])\s*", "", s)
        if s == before:
            break
    return s.strip().strip("·-—").strip()


def _doi_norm(d):
    """DOI 归一：统一走 kb_lib.norm_doi（会截断尾部粘连的中文标点，实测库里有 15 条此类污染）。"""
    return K.norm_doi(d)


def parse_manifest_md(path):
    """从任意 md 清单里尽力抽 (title, doi)。

    历史上至少有两种格式，都被支持：
      A) lit_fetch 产出：`### N. 标题` + `- **DOI**：[10.x](url)`
      B) 手工/到货记录：`- 标题 · 期刊` + 下一行 `  DOI`
    因为匹配主键是 DOI，标题解析不完美也可以接受（只在 DOI 缺失时用）。
    """
    out = []
    try:
        text = K.read_text(path)
    except OSError:
        return out
    lines = text.split("\n")
    cur_title = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        # 标题候选：标题行 / 列表项 / 三级标题
        is_title_line = (s.startswith("### ") or s.startswith("- ")
                         or re.match(r"^\d+\.\s", s))
        if is_title_line and not DOI_RE.search(s):
            t = _clean_title(s)
            # 排除元数据行（期刊/作者/失败原因/日期等）
            if t and not re.match(r"^(期刊|主要作者|通讯作者|DOI|自动失败原因|时间窗|合计|"
                                  r"Journal|Authors|Published|来源|备注)[：:]", t) \
                    and len(t) >= 12:
                cur_title = t
        dm = DOI_RE.search(s)
        if dm:
            doi = _doi_norm(dm.group(0))
            # 同一行里可能既有标题又有 DOI
            t = _clean_title(DOI_RE.sub("", s))
            title = t if len(t) >= 12 else (cur_title or "")
            out.append({"doi": doi, "title": title, "source": path})
    return out


def _iter_records(data):
    """容忍归档层里的多种 JSON 形状：{papers:[...]} / 纯列表 / {items:[...]} / 单篇 dict。"""
    if isinstance(data, dict):
        if isinstance(data.get("papers"), list):
            return [r for r in data["papers"] if isinstance(r, dict)]
        for k in ("items", "records", "results", "entries"):
            if isinstance(data.get(k), list):
                return [r for r in data[k] if isinstance(r, dict)]
        return [data]
    if isinstance(data, list):
        return [r for r in data if isinstance(r, dict)]
    return []


def parse_candidate_json(path):
    """从任意候选/清单 JSON 里抽 (doi, title, journal, date)。

    归档层里既有 `lit_discover` 的 {papers:[...]}，也有历史上手工产出的纯列表
    （digest-parsed/keep、batch_*.json、manual*_pages.json）——形状不一，一律容忍，
    取不到 DOI 时也保留标题用于后续模糊匹配。
    """
    out = []
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception:                                          # noqa: BLE001
        return out
    for r in _iter_records(data):
        doi = r.get("doi") or r.get("doiurl") or r.get("DOI") or ""
        m = DOI_RE.search(str(doi))
        doi = _doi_norm(m.group(0)) if m else ""
        title = (r.get("title") or r.get("md") or "").strip()
        if not (doi or title):
            continue
        out.append({"doi": doi, "title": title,
                    "journal": r.get("journal") or "",
                    "publication_date": r.get("publication_date") or r.get("date") or "",
                    "source": path})
    return out


def build_pool(extra_json=None, verbose=True):
    """汇总匹配池：候选 JSON 优先（字段全），md 清单补充（覆盖只有清单的情况）。

    🔴 **新旧两处都扫**（2026-10-10 迁移窗口期纪律）：
    运行产物已从 `_archive/lit-runs/` 搬到 `raw/notes/lit-watch/`，但历史候选池仍在旧处。
    若只扫新处，**历史那批候选全部匹配不上 → 收编时每篇都进 `_unmatched/`**。
    这是本工具最高危的一处路径耦合，故两个根都查，且旧根去掉时只少一条注释。
    """
    entries, seen = [], set()
    runs = K.lit_runs_dir(K.load_lit_config())
    # ⚠️ 2026-10-11：`_archive` 归并（13→5 组）后，旧运行根在 `_archive/lit-watch/lit-runs`。
    #    不改的话，**历史候选池会整体从匹配池里消失** ⇒ 那批曾按旧清单下载的 PDF
    #    全部匹配不上、统统进 `_unmatched/`。这是本工具最高危的一处路径耦合。
    legacy = os.path.join(K.VAULT, "_archive", "lit-watch", "lit-runs")
    json_globs = [
        # 新根（含 archive-pool/ 与 picks/）
        os.path.join(runs, "**", "cand*.json"),
        os.path.join(runs, "picks", "*.json"),
        os.path.join(runs, "*.json"),
        # 旧根（迁移前产出的候选池）
        os.path.join(legacy, "**", "cand*.json"),
        os.path.join(legacy, "picks", "*.json"),
        os.path.join(legacy, "*.json"),
    ]
    for g in json_globs:
        for p in glob.glob(g, recursive=True):
            base = os.path.basename(p)
            if base.startswith(("digest-", "fetch_result")):
                continue
            for e in parse_candidate_json(p):
                key = e["doi"] or _clean_title(e["title"]).lower()
                if key and key not in seen:
                    seen.add(key)
                    entries.append(e)
    if extra_json:
        for p in extra_json:
            for e in parse_candidate_json(p):
                key = e["doi"] or _clean_title(e["title"]).lower()
                if key and key not in seen:
                    seen.add(key)
                    entries.append(e)
    # 手动下载清单：新根优先，旧根回退（两个目录都扫，条目按 DOI/标题去重）
    cfg = {}
    try:
        cfg = K.load_lit_config()
    except Exception:                                          # noqa: BLE001
        pass
    # 🔴 2026-10-10 修正：清单有**两个家族**，此前只扫了一个。
    #   · 阶段B（lit_fetch）写 `<runs_dir>/downloads/manifest-<ts>.md`
    #   · 阶段A（lit_discover/lit_daily）写 `<runs_dir>/daily/<日期>/manifest_<方向>.md`
    #   旧实现只 glob `downloads/*.md` ⇒ **用户在阶段A 清单上照着下载的那批，
    #   收编时匹配池里没有它们的清单条目**（好在同日的 `cand_*.json` 是递归扫的，
    #   多数情况下还能靠候选 JSON 匹配上——但"JSON 被清理、只剩清单"时就会全进 `_unmatched/`）。
    #   ⇒ 现在递归扫两个家族，新旧根都扫。
    # 🔴 2026-10-11：`raw/_park/downloads` 已随 `raw/_park` 解散迁入归档层
    #   （`_archive/retired/quarantine/_park-downloads`）。路径必须同步改，
    #   否则**历史手动下载清单**（用户当时按它下载的那批）会从匹配池里消失。
    LEGACY_PARK_DOWNLOADS = os.path.join(
        K.VAULT, "_archive", "retired", "quarantine", "_park-downloads")
    dl_globs = []
    for root in (K.lit_runs_dir(cfg, "downloads"), LEGACY_PARK_DOWNLOADS):
        dl_globs.append(os.path.join(root, "*.md"))
    for root in (runs, legacy):
        dl_globs.append(os.path.join(root, "**", "manifest*.md"))
    n_md = 0
    seen_md = set()
    for g in dl_globs:
        for p in sorted(glob.glob(g, recursive=True)):
            if p in seen_md:
                continue
            seen_md.add(p)
            got = parse_manifest_md(p)
            n_md += len(got)
            for e in got:
                key = e["doi"] or _clean_title(e["title"]).lower()
                if key and key not in seen:
                    seen.add(key)
                    entries.append(e)
    if verbose:
        print(f"[池] 候选 JSON + md 清单合计 {len(entries)} 条唯一记录"
              f"（md 清单贡献 {n_md} 条原始记录）")
    return entries


def index_pool(entries):
    by_doi, with_title = {}, []
    for e in entries:
        if e["doi"]:
            by_doi.setdefault(e["doi"], e)
        if e.get("title"):
            with_title.append(e)
    return by_doi, with_title


def known_dois():
    """已在库（本机文献目录）的 DOI 集合，用于"这篇我已经有了"的判断。"""
    c = _cfg()
    p = (c.get("paths") or {}).get("catalogue") or os.path.join(
        K.lit_runs_dir(c, "state"), "local_lit_catalogue.json")
    out = set()
    if not os.path.exists(p):
        return out
    try:
        with open(p, encoding="utf-8") as f:
            for rec in (json.load(f).get("papers") or []):
                d = _doi_norm(rec.get("doi"))
                if d:
                    out.add(d)
    except Exception:                                          # noqa: BLE001
        pass
    return out


# ---------------------------------------------------------------- PDF 侧

def tokens(s):
    return set(w for w in re.findall(r"[a-z0-9]+", (s or "").lower()) if len(w) >= 4)


def pdf_probe(path, pages=2):
    """读 PDF 前几页文本与元数据，返回 (doi, text)。失败返回 (None, '')。"""
    try:
        import fitz
    except ImportError:
        raise SystemExit("[!] 需要 PyMuPDF：pip install pymupdf（用于读 PDF 首页 DOI）")
    with fitz.open(path) as doc:
        if doc.needs_pass:
            return None, ""
        n = min(pages, doc.page_count)
        text = "".join(doc[i].get_text() for i in range(n))
        meta = doc.metadata or {}
        for key in ("doi", "subject", "keywords", "title"):
            m = DOI_RE.search(str(meta.get(key) or ""))
            if m:
                return _doi_norm(m.group(0)), text
    m = DOI_RE.search(text)
    return (_doi_norm(m.group(0)) if m else None), text


def match_one(path, by_doi, with_title, min_score=0.5, margin=0.15):
    """返回 (match_entry|None, how, score, doi)。不猜：候选过于接近时判 ambiguous。"""
    doi, text = pdf_probe(path)
    if doi and doi in by_doi:
        return by_doi[doi], f"doi={doi}", 1.0, doi
    ct = tokens(text)
    scored = []
    for e in with_title:
        tt = tokens(e["title"])
        if not tt:
            continue
        overlap = len(ct & tt)
        if overlap < 3:                      # 少于 3 个词重叠一律不算（防单词偶合）
            continue
        scored.append((len(ct & tt) / len(tt), overlap, e))
    if not scored:
        return None, "no-match", 0.0, doi
    scored.sort(key=lambda x: (-x[0], -x[1]))
    best = scored[0]
    second = scored[1][0] if len(scored) > 1 else 0.0
    if best[0] < min_score:
        return None, f"weak-title({best[0]:.2f})", best[0], doi
    if best[0] - second < margin and second > 0:
        return None, f"ambiguous({best[0]:.2f} vs {second:.2f})", best[0], doi
    return best[2], f"title={best[0]:.2f}", best[0], doi


# ---------------------------------------------------------------- 主流程

def looks_like_pdf(path):
    try:
        with open(path, "rb") as f:
            return f.read(5).startswith(b"%PDF")
    except OSError:
        return False


def plan_import(inboxes, fresh_since=None, min_score=0.5, on_dup="skip",
                apply_pool=True, limit=0):
    pool = build_pool()
    by_doi, with_title = index_pool(pool)
    known = known_dois()
    print(f"[库] 本机文献目录已知 DOI：{len(known)} 条（用于识别「这篇我已有」）")

    pdfs = []
    for inbox in inboxes:
        if not os.path.isdir(inbox):
            print(f"[!] 收件箱不存在：{inbox}")
            continue
        for fn in sorted(os.listdir(inbox)):
            p = os.path.join(inbox, fn)
            if not os.path.isfile(p) or not fn.lower().endswith(".pdf"):
                continue
            if fresh_since:
                ts = datetime.datetime.combine(fresh_since, datetime.time.min).timestamp()
                if os.path.getmtime(p) < ts:
                    continue
            pdfs.append(p)
    if limit:
        pdfs = pdfs[:limit]
    print(f"[收件箱] 待处理 PDF：{len(pdfs)} 个（来自 {len(inboxes)} 个目录）")

    plan, unmatched, dups, bad = [], [], [], []
    for p in pdfs:
        if not looks_like_pdf(p):
            bad.append({"pdf": p, "why": "魔数不是 %PDF（可能是 HTML/下载不完整）"})
            continue
        hit, how, score, doi = match_one(p, by_doi, with_title, min_score=min_score)
        if not hit:
            unmatched.append({"pdf": p, "why": how, "doi": doi or ""})
            continue
        import lit_fetch
        newname = lit_fetch.pdf_filename(hit)
        dup = bool(hit.get("doi")) and hit["doi"] in known
        rec = {"src": p, "name": newname, "title": hit.get("title", ""),
               "doi": hit.get("doi", ""), "how": how, "score": score, "dup": dup}
        if dup and on_dup == "skip":
            dups.append(rec)
        else:
            plan.append(rec)
    return {"plan": plan, "unmatched": unmatched, "dups": dups, "bad": bad,
            "pool": len(pool), "inboxes": inboxes, "known": len(known)}


def render_report(res, dry=True):
    today = datetime.date.today().isoformat()
    L = [f"# 手动下载收编报告 · {today}", ""]
    L.append("> 由 `tools/lit_manual_import.py` 生成。" +
             ("**本次为干跑**（没有移动任何文件）。" if dry else "已实际搬移。"))
    L.append("")
    L.append(f"- 匹配池：{res['pool']} 条（候选 JSON ∪ 手动下载清单）")
    L.append(f"- 本机已建卡/已有 DOI：{res['known']} 条")
    L.append(f"- ✅ 可收编：{len(res['plan'])}　❓ 未匹配：{len(res['unmatched'])}　"
             f"♻️ 已在库被跳过：{len(res['dups'])}　⛔ 非 PDF：{len(res['bad'])}")
    L.append("")
    if res["plan"]:
        L.append("## ✅ 可收编（将改名为库内规范并移入 raw/pdf/）")
        L.append("")
        for r in res["plan"]:
            flag = "（库内已有同 DOI，按 --on-dup 处理）" if r["dup"] else ""
            L.append(f"- `{os.path.basename(r['src'])}` → `{r['name']}`　[{r['how']}]{flag}")
        L.append("")
    if res["unmatched"]:
        L.append("## ❓ 未匹配（需要你确认）")
        L.append("")
        L.append("这些文件的 DOI/标题没能在匹配池里找到对应候选。请看一眼："
                 "要么是清单外的论文（可手工命名），要么需要补进匹配池。")
        L.append("")
        for r in res["unmatched"]:
            L.append(f"- `{os.path.basename(r['pdf'])}`　原因：{r['why']}"
                     + (f"　PDF 内 DOI：{r['doi']}" if r["doi"] else ""))
        L.append("")
    if res["dups"]:
        L.append("## ♻️ 已在库（默认跳过，不重复收编）")
        L.append("")
        for r in res["dups"]:
            L.append(f"- `{os.path.basename(r['src'])}`　DOI {r['doi']}")
        L.append("")
    if res["bad"]:
        L.append("## ⛔ 不是 PDF（未处理）")
        L.append("")
        for r in res["bad"]:
            L.append(f"- `{os.path.basename(r['pdf'])}`　{r['why']}")
        L.append("")
    return "\n".join(L) + "\n"


def do_import(res, on_dup="skip"):
    dst_dir = os.path.join(K.VAULT, "raw", "pdf")
    os.makedirs(dst_dir, exist_ok=True)
    moved, skipped = [], []
    for r in res["plan"]:
        dst = os.path.join(dst_dir, r["name"])
        if os.path.exists(dst):
            skipped.append({**r, "why": "目标已存在同名文件"})
            continue
        shutil.move(r["src"], dst)
        moved.append({**r, "dst": dst})
    quarantined = []
    for r in res["unmatched"]:
        os.makedirs(QUARANTINE, exist_ok=True)
        dst = os.path.join(QUARANTINE, os.path.basename(r["pdf"]))
        if os.path.exists(dst):
            base, ext = os.path.splitext(os.path.basename(r["pdf"]))
            dst = os.path.join(QUARANTINE, f"{base}-{datetime.datetime.now():%H%M%S}{ext}")
        shutil.move(r["pdf"], dst)
        quarantined.append({**r, "dst": dst})
    return moved, skipped, quarantined


def append_ledger(records):
    lp = ledger_path()
    os.makedirs(os.path.dirname(lp), exist_ok=True)
    data = []
    if os.path.exists(lp):
        try:
            with open(lp, encoding="utf-8") as f:
                data = json.load(f)
        except Exception:                                      # noqa: BLE001
            data = []
    data.extend(records)
    tmp = lp + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    os.replace(tmp, lp)          # 原子写：台账被读到一半会污染"已在库"判断
    return lp


# ---------------------------------------------------------------- 自检

def selftest():
    print("=== lit_manual_import --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    # 清单里的标题清洗
    chk("清洗列表标记与加粗",
        _clean_title("- **Some Long Paper Title Here** · Journal") ==
        "Some Long Paper Title Here · Journal")
    chk("清洗编号与状态标记",
        _clean_title("### 1. [OA] Deep Learning for X") == "Deep Learning for X",
        _clean_title("### 1. [OA] Deep Learning for X"))

    # DOI 归一
    chk("DOI 归一（小写去尾标点）",
        _doi_norm("https://doi.org/10.1021/JACS.6C1.") == "https://doi.org/10.1021/jacs.6c1"
        or _doi_norm("10.1021/JACS.6C1.") == "10.1021/jacs.6c1")

    # md 清单解析：两种历史格式
    import tempfile
    tmp = os.path.join(tempfile.gettempdir(), "lit_manual_import_selftest")
    os.makedirs(tmp, exist_ok=True)
    try:
        a = os.path.join(tmp, "a.md")
        with open(a, "w", encoding="utf-8", newline="\n") as f:
            f.write("# 清单\n\n### 1. Title of Paper A\n- **期刊**：JACS（2026-10-01）\n"
                    "- **DOI**：[10.1021/jacs.6c00001](https://doi.org/10.1021/jacs.6c00001)\n"
                    "\n### 2. Title of Paper B\n- **DOI**：[10.1002/anie.20250002]"
                    "(https://doi.org/10.1002/anie.20250002)\n")
        b = os.path.join(tmp, "b.md")
        with open(b, "w", encoding="utf-8", newline="\n") as f:
            f.write("# 到货记录\n\n- Truncated Title One · Advanced Science\n"
                    "  10.1002/advs.76828\n- Truncated Title Two · ACS Nano\n"
                    "  10.1021/acsnano.6c10344\n")
        ra, rb = parse_manifest_md(a), parse_manifest_md(b)
        chk("解析 lit_fetch 式清单（### + DOI）",
            len(ra) == 2 and ra[0]["doi"] == "10.1021/jacs.6c00001"
            and "Paper A" in ra[0]["title"], json.dumps(ra, ensure_ascii=False)[:200])
        chk("解析到货记录式清单（标题行 + 下一行 DOI）",
            len(rb) == 2 and rb[0]["doi"] == "10.1002/advs.76828"
            and "Truncated Title One" in rb[0]["title"],
            json.dumps(rb, ensure_ascii=False)[:200])

        # 池索引 + 匹配（DOI 精确命中，不依赖标题）
        pool = [{"doi": "10.1021/jacs.6c00001", "title": "Title of Paper A",
                 "journal": "JACS", "publication_date": "2026-10-01", "source": a},
                {"doi": "", "title": "A Completely Different Paper About Zinc Dendrites",
                 "journal": "X", "publication_date": "2026-10-02", "source": a}]
        by_doi, with_title = index_pool(pool)
        chk("池索引按 DOI 命中", "10.1021/jacs.6c00001" in by_doi)

        # 非 PDF 识别
        html = os.path.join(tmp, "fake.pdf")
        with open(html, "wb") as f:
            f.write(b"<html>cloudflare</html>")
        chk("HTML 冒充 PDF 被识别", not looks_like_pdf(html))

        # 真实的 %PDF 文件应被识别
        try:
            import fitz
            real = os.path.join(tmp, "real.pdf")
            doc = fitz.open()
            pg = doc.new_page()
            pg.insert_text((72, 72), "Title of Paper A")
            pg.insert_text((72, 90), "https://doi.org/10.1021/jacs.6c00001")
            doc.save(real)
            doc.close()
            chk("%PDF 魔数识别", looks_like_pdf(real))
            hit, how, score, doi = match_one(real, by_doi, with_title)
            chk("按 PDF 内 DOI 精确匹配", hit is not None and how.startswith("doi="),
                f"{how} {doi}")
        except ImportError:
            chk("（无 PyMuPDF，跳过真实 PDF 匹配用例）", True)

        # 报告渲染包含四个分区标题
        res = {"plan": [{"src": "C:/x/1.pdf", "name": "N.pdf", "title": "t", "doi": "d",
                         "how": "doi=d", "score": 1.0, "dup": False}],
               "unmatched": [{"pdf": "C:/x/2.pdf", "why": "no-match", "doi": "d2"}],
               "dups": [], "bad": [], "pool": 2, "inboxes": [], "known": 1}
        rp = render_report(res, dry=True)
        chk("报告含可收编/未匹配分区与干跑声明",
            "可收编" in rp and "未匹配" in rp and "干跑" in rp)

        # 🆕 2026-10-10：本工具最高危的一处耦合 —— 匹配池的根。
        #    运行产物已搬出 _archive/，若 glob 不同时覆盖新旧两处，
        #    历史候选全部匹配不上 ⇒ 收编时每篇都进 _unmatched/。
        runs_tmp = os.path.join(tmp, "lit-watch")
        pool_dir = os.path.join(runs_tmp, "archive-pool")
        os.makedirs(pool_dir, exist_ok=True)
        with open(os.path.join(pool_dir, "cand_battery.json"), "w", encoding="utf-8") as f:
            json.dump({"papers": [{"doi": "10.9999/newroot.1",
                                   "title": "New Root Candidate Paper"}]}, f)
        with open(os.path.join(runs_tmp, "downloads"), "w") as f:
            pass
        os.remove(os.path.join(runs_tmp, "downloads"))
        os.makedirs(os.path.join(runs_tmp, "downloads"), exist_ok=True)
        with open(os.path.join(runs_tmp, "downloads", "手动下载清单.md"),
                  "w", encoding="utf-8") as f:
            f.write("# 清单\n\n### 1. From The New Downloads Dir\n"
                    "- **DOI**：[10.9999/newroot.2](https://doi.org/10.9999/newroot.2)\n")
        _orig_cfg = K.load_lit_config
        try:
            K.load_lit_config = lambda *a, **k: {"paths": {"runs_dir": runs_tmp},
                                                 "paths_rel": {"runs_dir": "raw/notes/lit-watch"}}
            pool2 = build_pool(verbose=False)
        finally:
            K.load_lit_config = _orig_cfg
        dois2 = {e["doi"] for e in pool2}
        chk("匹配池扫到**新根**的候选 JSON",
            "10.9999/newroot.1" in dois2, str(sorted(dois2)[:5]))
        chk("匹配池扫到**新根**的手动下载清单",
            "10.9999/newroot.2" in dois2, str(sorted(dois2)[:5]))
        # 🆕 2026-10-10 回归夹具：阶段A 的清单在 `daily/<日期>/manifest_*.md`（**另一个家族**），
        #    旧实现只 glob `downloads/*.md` ⇒ **实测 `downloads/` 下 0 个 md**，
        #    即整个 md 清单机制在新布局下**一条都没扫到**（8 份 daily 清单全部隐身）。
        #    这里只放一份 daily 清单、**不放候选 JSON**，断言条目仍进池。
        daydir = os.path.join(runs_tmp, "daily", "2026-10-10")
        os.makedirs(daydir, exist_ok=True)
        with open(os.path.join(daydir, "manifest_battery.md"), "w",
                  encoding="utf-8") as f:
            f.write("# 清单\n\n### 1. From The Daily Manifest\n"
                    "- **DOI**：[10.9999/dailyman.1](https://doi.org/10.9999/dailyman.1)\n")
        try:
            K.load_lit_config = lambda *a, **k: {"paths": {"runs_dir": runs_tmp},
                                                 "paths_rel": {"runs_dir": "raw/notes/lit-watch"}}
            pool3 = build_pool(verbose=False)
        finally:
            K.load_lit_config = _orig_cfg
        dois3 = {e["doi"] for e in pool3}
        chk("匹配池扫到 daily/<日期>/manifest_*.md（阶段A 清单家族）",
            "10.9999/dailyman.1" in dois3, str(sorted(dois3)[:5]))
        chk("两个清单家族都进池（互不遮蔽）",
            {"10.9999/newroot.2", "10.9999/dailyman.1"} <= dois3, str(sorted(dois3)[:5]))
        chk("台账落点不在 _archive/ 下",
            "_archive" not in ledger_path().replace("\\", "/"))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI

def main():
    ap = argparse.ArgumentParser(description="把手动下载的 PDF 按库内规范收编进 raw/pdf/")
    ap.add_argument("--inbox", nargs="*", default=[], help="收件箱目录（默认 raw/pdf/Manual Download）")
    ap.add_argument("--fresh-since", default="", help="只处理该日期之后修改的文件（YYYY-MM-DD）")
    ap.add_argument("--min-score", type=float, default=0.5, help="标题匹配阈值（默认 0.5）")
    ap.add_argument("--on-dup", choices=["skip", "import"], default="skip",
                    help="已在库的文件：skip（默认，列入报告）/ import（照样收编）")
    ap.add_argument("--limit", type=int, default=0, help="最多处理几个文件（0=全部）")
    ap.add_argument("--pool-stats", action="store_true", help="只统计匹配池")
    ap.add_argument("--report", default="",
                    help="报告落点（默认 <runs_dir>/downloads/手动导入报告.md）")
    ap.add_argument("--apply", action="store_true", help="真正搬移（默认干跑）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    inboxes = args.inbox or [DEFAULT_INBOX]
    if args.pool_stats:
        pool = build_pool()
        from collections import Counter
        c = Counter(os.path.basename(os.path.dirname(e["source"])) or "?" for e in pool)
        print(f"匹配池 {len(pool)} 条，来源分布：")
        for k, v in c.most_common():
            print(f"  {v:5}  {k}")
        nodoi = sum(1 for e in pool if not e["doi"])
        print(f"  无 DOI 的条目：{nodoi}（只能靠标题匹配）")
        return 0

    since = None
    if args.fresh_since:
        since = datetime.datetime.strptime(args.fresh_since, "%Y-%m-%d").date()

    res = plan_import(inboxes, fresh_since=since, min_score=args.min_score,
                      on_dup=args.on_dup, limit=args.limit)
    report = render_report(res, dry=not args.apply)
    rp = args.report or os.path.join(downloads_dir(), "手动导入报告.md")
    try:
        os.makedirs(os.path.dirname(rp), exist_ok=True)
        with open(rp, "w", encoding="utf-8", newline="\n") as f:
            f.write(report)
        print(f"报告：{rp}")
    except OSError as e:                       # 只读环境（或沙箱）下也要能看到结果
        print(f"[warn] 报告写不进去（{rp}）：{e}", file=sys.stderr)

    if not args.apply:
        print("（干跑结束。确认无误后加 --apply 才会改名与搬移）")
        return 0

    moved, skipped, quarantined = do_import(res, on_dup=args.on_dup)
    led = append_ledger([{"at": datetime.datetime.now().isoformat(timespec="seconds"),
                          "src": m["src"], "dst": m["dst"], "doi": m["doi"],
                          "how": m["how"], "title": m["title"]} for m in moved])
    print(f"\n已收编 {len(moved)} 个 → raw/pdf/")
    print(f"隔离未匹配 {len(quarantined)} 个 → {QUARANTINE}")
    if skipped:
        print(f"跳过（目标同名）{len(skipped)} 个")
    print(f"台账：{led}")
    print("\n下一步：python tools/lit_batch.py --pending   # 看哪些 PDF 还没提取")
    return 0


if __name__ == "__main__":
    sys.exit(main())
